const proxy = (proxyUrl: string | null | undefined): Record<string, string> =>
  proxyUrl ? { proxyUrl } : {};

export function createCardsClient(
  call: <T>(command: string, args?: Record<string, unknown>) => Promise<T>
): CardsClient {
  return {
    cardsBootstrap: () => call<CardsBootstrap>("cards_bootstrap"),
    cardsPacks: () => call<CardPackRow[]>("cards_packs"),
    cardsPreparePacks: (args) =>
      call<PackPreparation>("cards_prepare_packs", proxy(args.proxyUrl)),
    cardsAckPreparedPacks: () => call<number>("cards_ack_prepared_packs"),
    cardsOpenPack: (args) =>
      call<PackOpening>("cards_open_pack", {
        packId: args.packId,
        ...proxy(args.proxyUrl),
      }),
    cardsCollection: (args) =>
      call<CollectionPage>("cards_collection", {
        kind: args.kind,
        rarity: args.rarity,
        variant: args.variant,
        sort: args.sort,
        sortDir: args.sortDir,
        query: args.query,
        page: args.page,
        pageSize: args.pageSize,
        ...proxy(args.proxyUrl),
      }),
    cardsResetCollection: () => call<number>("cards_reset_collection"),
    cardsCollections: (args) =>
      call<CollectionShelfItem[]>("cards_collections", {
        sort: args.sort,
        sortDir: args.sortDir,
        ...proxy(args.proxyUrl),
      }),
    cardsCardVariants: (args) =>
      call<CollectionItem[]>("cards_card_variants", {
        kind: args.kind,
        entityId: args.entityId,
      }),
    cardsGallery: (args) =>
      call<CardGallery>("cards_gallery", {
        kind: args.kind,
        entityId: args.entityId,
        ...proxy(args.proxyUrl),
      }),
    cardsSetPreferredImage: (args) =>
      call<number>("cards_set_preferred_image", {
        kind: args.kind,
        entityId: args.entityId,
        imageUrl: args.imageUrl ?? null,
      }),
    cardsSetCardVariant: (args) =>
      call<number>("cards_set_card_variant", {
        kind: args.kind,
        entityId: args.entityId,
        variant: args.variant,
      }),
    cardsCardFavorite: (args) =>
      call<boolean>("cards_card_favorite", {
        kind: args.kind,
        entityId: args.entityId,
      }),
    cardsSetCardFavorite: (args) =>
      call<boolean>("cards_set_card_favorite", {
        kind: args.kind,
        entityId: args.entityId,
        favorite: args.favorite,
      }),
    cardsAnimeCollection: (args) =>
      call<AnimeCollectionPage>("cards_anime_collection", {
        animeId: args.animeId,
        kind: args.kind,
        ...proxy(args.proxyUrl),
      }),
    cardsCollectionRoster: (args) =>
      call<CollectionRosterPage>("cards_collection_roster", {
        mediaId: args.mediaId,
        kind: args.kind,
        page: args.page,
        ...proxy(args.proxyUrl),
      }),
    cardsUnread: (args) =>
      call<CardsUnread>("cards_unread", {
        packsSince: args.packsSince,
        cardsSince: args.cardsSince,
      }),
    cardsStats: () => call<CardsStats>("cards_stats"),
    cardsDust: (args) =>
      call<DustResult>("cards_dust", {
        kind: args.kind,
        entityId: args.entityId,
        rarity: args.rarity,
        variant: args.variant,
      }),
    cardsBuyPack: (args) =>
      call<PurchaseResult>("cards_buy_pack", { packKind: args.packKind }),
    cardsStarterStatus: (args) =>
      call<StarterStatus>("cards_starter_status", proxy(args.proxyUrl)),
    cardsGrantStarter: (args) =>
      call<GrantResult>("cards_grant_starter", {
        userId: args.userId,
        ...proxy(args.proxyUrl),
      }),
    cardsCreateGift: (args) =>
      call<CreatedGift>("cards_create_gift", {
        kind: args.kind,
        entityId: args.entityId,
      }),
    cardsClaimGift: (args) => {
      const payload =
        args.cards && args.cards.length > 0
          ? {
              giftId: args.giftId,
              kind: args.kind,
              entityId: args.entityId,
              cards: args.cards,
            }
          : {
              giftId: args.giftId,
              kind: args.kind,
              entityId: args.entityId,
              rarity: args.rarity,
              variant: args.variant,
              value: args.value,
            };
      return call<GiftCard[]>("cards_claim_gift", payload);
    },
    cardsGifts: () => call<GiftItem[]>("cards_gifts"),
    cardsMarkGiftClaimed: (args) =>
      call<GiftItem>("cards_mark_gift_claimed", { giftId: args.giftId }),
    cardsDeleteGift: (args) =>
      call<GiftDeleteResult>("cards_delete_gift", { giftId: args.giftId }),
  };
}

export function createDailyClient(
  call: <T>(command: string, args?: Record<string, unknown>) => Promise<T>
): DailyClient {
  return {
    bootstrap: (args) => call<DailyBootstrap>("daily_game_bootstrap", { day: args.day }),
    searchIndex: () => call<DailySearchEntry[]>("daily_game_search_index"),
    prepare: (args) =>
      call<DailyFramesView>("daily_game_prepare", {
        day: args.day,
        mode: args.mode,
        ...proxy(args.proxyUrl),
      }),
    revealFrames: (args) =>
      call<DailyFramesView>("daily_game_reveal_frames", {
        day: args.day,
        ...proxy(args.proxyUrl),
      }),
    prepareOp: (args) =>
      call<DailyOpView>("daily_game_prepare_op", {
        day: args.day,
        ...proxy(args.proxyUrl),
      }),
    prepareAudio: (args) =>
      call<DailyOpView>("daily_game_prepare_audio", {
        day: args.day,
        ...proxy(args.proxyUrl),
      }),
    guessAudio: (args) =>
      call<DailyOpGuessView>("daily_game_guess_audio", {
        day: args.day,
        mediaId: args.mediaId,
        guessedTitles: args.guessedTitles,
      }),
    skipAudio: (args) => call<DailyOpGuessView>("daily_game_skip_audio", { day: args.day }),
    guessOp: (args) =>
      call<DailyOpGuessView>("daily_game_guess_op", {
        day: args.day,
        mediaId: args.mediaId,
        guessedTitles: args.guessedTitles,
      }),
    skipOp: (args) => call<DailyOpGuessView>("daily_game_skip_op", { day: args.day }),
    guess: (args) =>
      call<DailyGuessView>("daily_game_guess", {
        day: args.day,
        mode: args.mode,
        mediaId: args.mediaId,
        guessedTitles: args.guessedTitles,
        ...proxy(args.proxyUrl),
      }),
    skip: (args) =>
      call<DailyGuessView>("daily_game_skip", {
        day: args.day,
        mode: args.mode,
        ...proxy(args.proxyUrl),
      }),
    history: (args) =>
      call<DailyHistoryItem[]>("daily_game_history", {
        day: args.day,
        mode: args.mode,
        limit: args.limit,
      }),
    reset: () => call<void>("daily_game_reset"),
  };
}
